VIEWS=[('photo-shoot', "tutEnd();__goto('city');__setClock(null,12);setJob('photo');S.ptTut=1;const d=pt();d.o={id:'px',kind:'family',spot:'park',bg:'fountain',who:['n1','n2','s1'],pet:null,st:'go'};P.x=-22;P.z=11.4;P.yaw=Math.PI;P.pitch=.02;__run(2);ptSetup();for(const w of WALKERS)if(Math.hypot(w.x-P.x,w.z-P.z)<9){w.x=WP[w.home][0];w.z=WP[w.home][1];w.node=w.home;w.prev=-1;}for(const q of PET_ACTORS){const f=P.yaw;q.x=P.x+Math.sin(f)*2.5;q.z=P.z+Math.cos(f)*2.5;}for(const c of CARS)if(Math.hypot(c.x-P.x,c.z-P.z)<16){c.d+=c.total/2;carPlace(c);}ptPoseCard(0);closePanel();closePanel();for(const m of PHO.group)m.pose='wave';const g=PHO.group,cx=g.reduce((a,m)=>a+m.x,0)/g.length,cz=g.reduce((a,m)=>a+m.z,0)/g.length,f=g[0].face;P.x=cx+Math.sin(f)*4.4;P.z=cz+Math.cos(f)*4.4;P.yaw=f;P.pitch=innerWidth<innerHeight?-.17:-.04;for(const w of WALKERS)if(Math.hypot(w.x-P.x,w.z-P.z)<9){w.x=WP[w.home][0];w.z=WP[w.home][1];w.node=w.home;w.prev=-1;}for(const q of PET_ACTORS){const f=P.yaw;q.x=P.x+Math.sin(f)*2.5;q.z=P.z+Math.cos(f)*2.5;}for(const c of CARS)if(Math.hypot(c.x-P.x,c.z-P.z)<16){c.d+=c.total/2;carPlace(c);}"), ('photo-side', "(()=>{const g=PHO.group.filter(q=>q.kind==='person');const m=g.find(q=>q.nm==='Mia')||g[0];const f=m.face;P.x=m.x+Math.sin(f)*1.9+Math.cos(f)*.7;P.z=m.z+Math.cos(f)*1.9-Math.sin(f)*.7;P.yaw=Math.atan2(-(m.x-P.x),-(m.z-P.z));P.pitch=.05;return m.nm;})()"), ('pill-report', "[...document.querySelectorAll('body *')].filter(e=>{const b=e.getBoundingClientRect();return b.width>0&&b.right>780&&b.left<840&&b.top<140&&b.bottom>100&&getComputedStyle(e).visibility!=='hidden'&&e.children.length<3;}).map(e=>{const b=e.getBoundingClientRect();return [e.id||e.className,(e.textContent||'').trim().slice(0,30),Math.round(b.left),Math.round(b.top),Math.round(b.right),Math.round(b.bottom)];})")]
